// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
contract LendingPool {
    mapping(address => uint256) public collateral;
    mapping(address => uint256) public debt;
    function deposit() external payable { collateral[msg.sender] += msg.value; }
    function borrow(uint256 amount) external {
        require(debt[msg.sender] + amount <= collateral[msg.sender] / 2);
        debt[msg.sender] += amount;
        (bool ok,) = msg.sender.call{value: amount}(""); require(ok);
    }
    function withdraw(uint256 amount) external {
        require(amount <= collateral[msg.sender]);
        collateral[msg.sender] -= amount;
        (bool ok,) = msg.sender.call{value: amount}(""); require(ok);
    }
    receive() external payable {}
}
